@Override
    protected Collection<Class<? extends Plugin>> nodePlugins() {
        return List.of(TestTimedQueryPlugin.class);
    }

static class TimedQuery extends Query {
        private final long time;

        TimedQuery(long time) {
            this.time = time;
        }

        @Override
        public Weight createWeight(IndexSearcher searcher, ScoreMode scoreMode, float boost) {
            return new Weight(this) {
                @Override
                public Explanation explain(LeafReaderContext leafReaderContext, int i) {
                    return null;
                }

                @Override
                public Scorer scorer(LeafReaderContext leafReaderContext) {
                    DocIdSetIterator iterator = DocIdSetIterator.all(leafReaderContext.reader().maxDoc());
                    return new Scorer(this) {
                        @Override
                        public DocIdSetIterator iterator() {
                            return iterator;
                        }

                        @Override
                        public float getMaxScore(int i) {
                            return Float.POSITIVE_INFINITY;
                        }

                        @Override
                        public float score() {
                            try {
                                Thread.sleep(time);
                            } catch (InterruptedException e) {
                                Thread.currentThread().interrupt();
                            }
                            return time;
                        }

                        @Override
                        public int docID() {
                            return iterator.docID();
                        }
                    };
                }

                @Override
                public boolean isCacheable(LeafReaderContext leafReaderContext) {
                    return false;
                }
            };
        }

        @Override
        public String toString(String s) {
            return "timed";
        }

        @Override
        public void visit(QueryVisitor queryVisitor) {
            queryVisitor.visitLeaf(this);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            TimedQuery that = (TimedQuery) o;
            return time == that.time;
        }

        @Override
        public int hashCode() {
            return Objects.hashCode(time);
        }
    }

public static class TestTimedQueryPlugin extends Plugin implements SearchPlugin {

        @Override
        public List<QuerySpec<?>> getQueries() {
            return List.of(new QuerySpec<>(new ParseField("timed"), TimedQueryBuilder::new, TimedQueryBuilder::fromXContent));
        }
    }

public void testRescoreWithTimeout() throws Exception {
        // no dummy docs since merges can change scores while we run queries.
        int numDocs = indexRandomNumbers("whitespace", -1, false);

        String intToEnglish = English.intToEnglish(between(0, numDocs - 1));
        String query = intToEnglish.split(" ")[0];
        assertResponse(
            prepareSearch().setSearchType(SearchType.QUERY_THEN_FETCH)
                .setQuery(QueryBuilders.matchQuery("field1", query).operator(Operator.OR))
                .setSize(10)
                .addRescorer(new QueryRescorerBuilder(new TimedQueryBuilder(500)).windowSize(100))
                .setTimeout(TimeValue.timeValueMillis(10)),
            r -> assertTrue(r.isTimedOut())
        );
    }

public void checkCancellation() {
        if (isCancelled != null) {
            isCancelled.run();
        }
    }

public void setCancellationChecker(Runnable isCancelled) {
        this.isCancelled = isCancelled;
    }

private static Runnable getCancellationChecks(SearchContext context) {
        List<Runnable> cancellationChecks = new ArrayList<>();
        if (context.lowLevelCancellation()) {
            cancellationChecks.add(() -> {
                final SearchShardTask task = context.getTask();
                if (task != null) {
                    task.ensureNotCancelled();
                }
            });
        }

        final Runnable timeoutRunnable = QueryPhase.getTimeoutCheck(context);
        if (timeoutRunnable != null) {
            cancellationChecks.add(timeoutRunnable);
        }

        return () -> {
            for (var check : cancellationChecks) {
                check.run();
            }
        };
    }

